#include <Keypad.h>
#include <Servo.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Keypad Door Lock Simulation
// Enter a 4-digit code; a servo "unlocks" on a correct match.

const char CORRECT_CODE[] = "1234"; // change this to your own code
const int CODE_LENGTH = 4;

const byte ROWS = 4;
const byte COLS = 4;
char keys[ROWS][COLS] = {
  {'1','2','3','A'},
  {'4','5','6','B'},
  {'7','8','9','C'},
  {'*','0','#','D'}
};
byte rowPins[ROWS] = {2, 3, 4, 5};
byte colPins[COLS] = {6, 7, 8, 9};
Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

const int SERVO_PIN = 10;
const int BUZZER_PIN = 11;
Servo lockServo;

LiquidCrystal_I2C lcd(0x27, 16, 2);

char enteredCode[CODE_LENGTH + 1];
int enteredCount = 0;

void setup() {
  lockServo.attach(SERVO_PIN);
  lockServo.write(0); // 0 degrees = locked

  pinMode(BUZZER_PIN, OUTPUT);

  lcd.init();
  lcd.backlight();
  promptForCode();
}

void loop() {
  char key = keypad.getKey();
  if (!key) return; // no key pressed this loop

  if (key == '*') { // '*' clears a mistaken entry
    enteredCount = 0;
    promptForCode();
    return;
  }

  if (enteredCount < CODE_LENGTH && isDigit(key)) {
    enteredCode[enteredCount] = key;
    enteredCount++;
    enteredCode[enteredCount] = '\0';

    lcd.setCursor(0, 1);
    lcd.print(enteredCode);

    if (enteredCount == CODE_LENGTH) {
      checkCode();
    }
  }
}

void checkCode() {
  if (strcmp(enteredCode, CORRECT_CODE) == 0) {
    lcd.clear();
    lcd.print("Access granted");
    lockServo.write(90); // 90 degrees = unlocked
    delay(3000);
    lockServo.write(0); // re-lock automatically
  } else {
    lcd.clear();
    lcd.print("Access denied");
    tone(BUZZER_PIN, 300, 500);
    delay(1500);
  }

  enteredCount = 0;
  promptForCode();
}

void promptForCode() {
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("Enter code:");
}
